<script>
(function($){
 const API='risk_dashboard_api.php',CSRF=<?php echo json_encode($csrf); ?>;let cache=null,opts=null,currentDetail=null,returnToDetail=false,studentPage=1;const STUDENTS_PER_PAGE=10;
 const esc=v=>$('<div>').text(v==null?'':v).html(),pct=v=>v==null?'—':(Number(v)*100).toFixed(1)+'%',num=(v,d=1)=>v==null?'—':Number(v).toFixed(d),badge=l=>'<span class="cr-badge cr-'+esc(l)+'">'+esc(l)+'</span>',gradeLabel=v=>String(v==null?'':v).replace(/°/g,'').trim()+'°';
 function query(action='dashboard'){let q=new URLSearchParams({action});[['search','#cr-search'],['level','#cr-level'],['grade','#cr-grade'],['section','#cr-section'],['course_id','#cr-course'],['risk_level','#cr-risk'],['bimestre','#cr-bim']].forEach(([k,s])=>{let v=$(s).val();if(v)q.set(k,v)});return q.toString()}
 function alertMsg(t,type='warning'){$('#cr-alert').html('<div class="alert alert-'+type+'">'+esc(t)+'</div>')}
 function card(label,value,tone,icon){return '<div class="col-xl-3 col-md-6 mb-3"><div class="cr-card"><div class="d-flex justify-content-between"><div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div><span class="cr-icon cr-'+tone+'"><i class="fas '+icon+'"></i></span></div></div></div>'}
 function populateOptions(o){opts=o||{};let cur=$('#cr-level').val(),html='<option value="">Todos</option>';for(let x of (opts.levels||[]))html+='<option'+(x===cur?' selected':'')+'>'+esc(x)+'</option>';$('#cr-level').html(html);let ch=$('#cr-course').val(),c='<option value="">Todos</option>';for(let x of (opts.courses||[]))c+='<option value="'+x.id+'"'+(String(x.id)===String(ch)?' selected':'')+'>'+esc(x.name)+'</option>';$('#cr-course').html(c);syncGrades()}
 function syncGrades(){let l=$('#cr-level').val(),old=$('#cr-grade').val(),arr=l?(opts?.grades?.[l]||[]):[...new Set(Object.values(opts?.grades||{}).flat())].sort((a,b)=>a-b),h='<option value="">Todos</option>';for(let g of arr)h+='<option value="'+g+'"'+(String(g)===String(old)?' selected':'')+'>'+g+'°</option>';$('#cr-grade').html(h);syncSections()}
 function syncSections(){let l=$('#cr-level').val(),g=$('#cr-grade').val(),old=$('#cr-section').val(),arr=(l&&g)?(opts?.sections?.[l+'|'+g]||[]):[],h='<option value="">Todas</option>';for(let s of arr)h+='<option'+(s===old?' selected':'')+'>'+esc(s)+'</option>';$('#cr-section').html(h)}
 async function load(){ studentPage=1; $('#cr-loading').removeClass('d-none');$('#cr-content').addClass('d-none');$('#cr-alert').empty();try{let r=await fetch(API+'?'+query(),{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo cargar el módulo.');cache=d;populateOptions(d.filters);render(d)}catch(e){alertMsg(e.message,'danger')}finally{$('#cr-loading').addClass('d-none')}}
 function render(d){$('#cr-content').removeClass('d-none');if(!d.model.available){alertMsg('El nuevo modelo v6 por curso todavía no está entrenado. Ejecuta el exportador y entrenamiento indicados en la documentación antes de interpretar alertas.','warning');}else if(!d.migration_ready){alertMsg('Las alertas por curso funcionan, pero falta la migración de intervenciones.','warning');}
  let s=d.summary||{};$('#cr-cards').html(card('Prioridad alta',s.high||0,'danger','fa-exclamation-triangle')+card('Prioridad media',s.medium||0,'warning','fa-exclamation-circle')+card('Cursos que requieren atención',s.attention_courses||0,'primary','fa-book-open')+card('Estudiantes evaluados',s.evaluated||0,'success','fa-users'));
  $('#cr-period').text(d.period?.base?'Se usó '+d.period.base+' bimestre cerrado → se estima '+d.period.target+' bimestre'+(d.period.cutoff?' · corte '+d.period.cutoff:''):'Se requiere un bimestre cerrado y el modelo v6.');
  renderStudentPage(d.students||[]);
  let ph='';for(let p of d.course_patterns||[]){ph+='<div class="cr-pattern"><strong>'+esc(p.course_name)+' · '+esc(gradeLabel(p.grado))+' '+esc(p.seccion)+'</strong><div class="cr-note">'+esc(p.nivel)+'</div><div class="mt-1">'+pct(p.critical_student_rate)+' del aula con promedio del curso en zona crítica</div><div class="cr-note">Promedio del aula: '+num(p.class_mean)+'</div></div>'}$('#cr-patterns').html(ph||'<div class="cr-empty">Sin patrones de aula suficientes.</div>');renderInterventions(d.interventions||[])
 }
 function renderStudentPage(students){
  const total=students.length,totalPages=Math.max(1,Math.ceil(total/STUDENTS_PER_PAGE));if(studentPage>totalPages)studentPage=totalPages;if(studentPage<1)studentPage=1;
  const start=(studentPage-1)*STUDENTS_PER_PAGE,end=Math.min(start+STUDENTS_PER_PAGE,total),visible=students.slice(start,end);let rows='';
  for(let x of visible){let courses='<ul class="cr-course-list">';for(let c of x.courses||[]){if(c.level==='Bajo'&&x.general.attention_courses>0)continue;courses+='<li>'+badge(c.level)+' <strong>'+esc(c.course_name)+'</strong> · '+pct(c.probability)+'</li>'}courses+='</ul>';if(courses==='<ul class="cr-course-list"></ul>')courses='<span class="text-muted">Sin cursos en alerta media/alta</span>';let a=x.attendance||{};rows+='<tr><td><strong>'+esc(x.student.name)+'</strong></td><td>'+esc(x.student.nivel)+'<br>'+esc(gradeLabel(x.student.grado))+' '+esc(x.student.seccion)+'</td><td>'+courses+'</td><td class="cr-att">'+(a.rate==null?'Sin datos suficientes':'Asistencia '+num(a.rate)+'%<br>Ausencias '+num(a.absent,0)+' · Tardanzas '+num(a.late,0))+'</td><td>'+badge(x.general.level)+'<div class="cr-note mt-1">'+x.general.attention_courses+' curso(s) requieren atención</div></td><td class="text-right"><button class="btn btn-sm btn-outline-primary cr-detail" data-id="'+x.student.id+'"><i class="fas fa-search mr-1"></i>Detalle</button></td></tr>'}
  $('#cr-students').html(rows||'<tr><td colspan="6" class="cr-empty">No hay estudiantes que coincidan con los filtros o el modelo v6 aún no está disponible.</td></tr>');
  $('#cr-count').text(total+' estudiante(s) mostrados');$('#cr-page-info').text(total?('Mostrando '+(start+1)+'–'+end+' de '+total+' · Página '+studentPage+' de '+totalPages):'Sin resultados');$('#cr-prev-page').prop('disabled',studentPage<=1||!total);$('#cr-next-page').prop('disabled',studentPage>=totalPages||!total);$('#cr-student-pagination').toggleClass('d-none',total<=STUDENTS_PER_PAGE)
 }
 function renderInterventions(rs){let h='';for(let r of rs){h+='<tr><td><strong>'+esc(r.student_name)+'</strong><div class="cr-note">'+esc(r.nivel)+' · '+esc(r.grado)+'° '+esc(r.seccion)+'</div></td><td>'+esc(r.course_name||'Intervención general histórica')+'</td><td>'+esc(r.intervention_type)+'<div class="cr-note">'+esc(r.title)+'</div></td><td><span class="cr-badge cr-status-'+String(r.status).replace(/\s+/g,'')+'">'+esc(r.status)+'</span></td><td>'+esc(r.followup_date||'—')+'</td><td>'+(r.risk_probability==null?'—':pct(r.risk_probability))+'</td><td class="text-right"><button class="btn btn-sm btn-outline-secondary cr-edit" data-id="'+r.id+'"><i class="fas fa-edit"></i></button></td></tr>'}$('#cr-interventions').html(h||'<tr><td colspan="7" class="cr-empty">Todavía no hay intervenciones registradas.</td></tr>')}
 function trendText(hist){if(!hist?.length)return 'Sin tendencia disponible';return hist.map(x=>x.bimester?['','I','II','III','IV'][x.bimester]+' '+num(x.course_mean_current):'').filter(Boolean).join(' → ')}
 function historical(h){if(!h?.length)return '<div class="cr-note">No hay años anteriores comparables para este curso.</div>';let out='<div class="cr-history border rounded">';for(let y of h){out+='<div class="cr-history-row"><strong>'+esc(y.year)+'</strong>: '+y.periods.map(p=>p.label+' '+num(p.mean)).join(' → ')+'</div>'}return out+'</div>'}
 async function detail(id){$('#cr-detail-sub').text('Cargando información académica...');$('#cr-detail-body').html('<div class="cr-loading py-4"><div class="spinner-border text-primary mb-2"></div><div>Calculando riesgo por curso...</div></div>');$('#crDetailModal').modal('show');try{let q=query('student')+'&student_id='+encodeURIComponent(id),r=await fetch(API+'?'+q,{credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo consultar el detalle.');currentDetail=d.prediction;renderDetail(d.prediction,d.course_interventions_ready)}catch(e){$('#cr-detail-body').html('<div class="alert alert-danger mb-0">'+esc(e.message)+'</div>')}}
 function renderDetail(p,intReady){let st=p.student,g=p.general;$('#cr-detail-sub').text(st.name+' · '+st.nivel+' · '+gradeLabel(st.grado)+' '+st.seccion+' · '+p.source_bimester_label+' → '+p.target_bimester_label);let h='<div class="row mb-3"><div class="col-md-4 mb-2"><div class="cr-kpi"><small>Prioridad general</small><strong>'+badge(g.level)+'</strong></div></div><div class="col-md-4 mb-2"><div class="cr-kpi"><small>Cursos que requieren atención</small><strong>'+g.attention_courses+'</strong></div></div><div class="col-md-4 mb-2"><div class="cr-kpi"><small>Mayor riesgo por curso</small><strong>'+esc(g.max_course_name||'—')+' · '+pct(g.max_course_probability)+'</strong></div></div></div>';
  h+='<div class="cr-warning-box mb-3"><strong>Importante:</strong> el porcentaje pertenece a cada curso y se calcula con el modelo predictivo. La prioridad general solo resume cuántos cursos están en nivel Alto/Medio.</div>';
  for(let c of p.courses){let f=c.features||{},low=f.low_grade_cells||0,graded=f.graded_cells||0,missing=f.missing_grade_cells||0,compCrit=f.critical_competency_count_current||0,compTotal=f.competencies_graded_current||0,streak=f.consecutive_critical_periods||0,priorPeriods=f.prior_years_periods_available||0;
   h+='<div class="cr-course"><div class="cr-course-head"><div><strong>'+esc(c.course_name)+'</strong><div class="cr-trend">'+esc(trendText(c.history_same_year))+'</div></div><div class="text-right">'+badge(c.level)+' <strong>'+pct(c.probability)+'</strong><div class="cr-note">riesgo en '+esc(p.target_bimester_label)+' bimestre</div></div></div><div class="cr-course-body"><div class="row">';
   h+='<div class="col-md-4"><div class="cr-info-line"><i class="fas fa-chart-line"></i>Promedio actual: <strong>'+num(f.course_mean_current)+'</strong></div><div class="cr-info-line"><i class="fas fa-history"></i>Promedio anterior: <strong>'+num(f.previous_course_mean)+'</strong></div><div class="cr-info-line"><i class="fas fa-exclamation-circle"></i>Bimestres críticos seguidos: <strong>'+num(streak,0)+'</strong></div><div class="cr-info-line"><i class="fas fa-ruler"></i>Referencia crítica: <strong>&lt; 10.5</strong></div><div class="cr-info-line"><i class="fas fa-file-alt"></i>Calificaciones bajas: <strong>'+low+' de '+graded+'</strong></div><div class="cr-info-line"><i class="fas fa-question-circle"></i>Calificaciones faltantes: <strong>'+missing+'</strong></div></div>';
   h+='<div class="col-md-4"><div class="cr-info-line"><i class="fas fa-clipboard-check"></i>Última evaluación: <strong>'+num(f.evaluation_mean_last)+'</strong></div><div class="cr-info-line"><i class="fas fa-chart-area"></i>Promedio últimas evaluaciones: <strong>'+num(f.evaluation_mean_recent3)+'</strong></div><div class="cr-info-line"><i class="fas fa-project-diagram"></i>Competencias críticas: <strong>'+num(compCrit,0)+' de '+num(compTotal,0)+'</strong></div><div class="cr-info-line"><i class="fas fa-user-check"></i>Asistencia: <strong>'+(f.attendance_rate_30d==null?'sin datos':num(f.attendance_rate_30d)+'%')+'</strong></div><div class="cr-info-line"><i class="fas fa-users"></i>Promedio del aula: <strong>'+num(f.class_course_mean_current)+'</strong></div><div class="cr-info-line"><i class="fas fa-arrows-alt-v"></i>Diferencia frente al aula: <strong>'+num(f.student_vs_class_mean)+'</strong></div></div>';
   h+='<div class="col-md-4"><strong class="cr-note">¿Por qué aparece esta alerta?</strong><ul class="cr-reasons">'+((c.reasons||[]).length?c.reasons.map(x=>'<li>'+esc(x)+'</li>').join(''):'<li>No hay un motivo simple dominante; la probabilidad surge de la combinación de señales aprendidas históricamente.</li>')+'</ul>'+(priorPeriods?'<div class="cr-note mt-2"><i class="fas fa-history mr-1"></i>El modelo dispone de <strong>'+num(priorPeriods,0)+'</strong> periodo(s) de años anteriores en este curso · promedio histórico <strong>'+num(f.prior_years_mean)+'</strong>.</div>':'<div class="cr-note mt-2">Sin historial previo suficiente del mismo curso en años anteriores.</div>')+'</div></div>';
   h+='<div class="mt-3"><strong class="cr-note">Evolución longitudinal del mismo curso</strong>'+historical(c.history_across_years)+'</div><div class="text-right mt-3">'+(intReady?'<button class="btn btn-sm btn-primary cr-new-int" data-student="'+st.id+'" data-course="'+c.course_id+'"><i class="fas fa-hands-helping mr-1"></i>Intervenir en '+esc(c.course_name)+'</button>':'<span class="cr-note">Ejecuta la migración de curso para registrar intervenciones específicas.</span>')+'</div></div></div>'
  }
  $('#cr-detail-body').html(h)
 }
 function openIntervention(studentId,courseId){
  let c=(currentDetail?.courses||[]).find(x=>Number(x.course_id)===Number(courseId));if(!c)return;
  let f=c.features||{},type=(f.attendance_rate_30d!=null&&Number(f.attendance_rate_30d)<85)||Number(f.absent_30d||0)>=3?'Seguimiento de asistencia':(Number(f.late_30d||0)>=3?'Plan de puntualidad':'Reforzamiento académico');
  $('#cr-int-student').val(studentId);$('#cr-int-course').val(courseId);$('#cr-int-type').val(type);$('#cr-int-title').val(type+' en '+c.course_name);$('#cr-int-label').html('<strong>'+esc(currentDetail.student.name)+'</strong><br>'+esc(c.course_name)+' · '+esc(c.level)+' · '+pct(c.probability));
  returnToDetail=true;
  $('#crDetailModal').one('hidden.bs.modal',function(){$('#crInterventionModal').modal('show')}).modal('hide')
}
 $(document).on('click','.cr-detail',function(){detail($(this).data('id'))});$(document).on('click','.cr-new-int',function(){openIntervention($(this).data('student'),$(this).data('course'))});
 $('#crInterventionModal').on('hidden.bs.modal',function(){if(returnToDetail&&currentDetail){returnToDetail=false;$('#crDetailModal').modal('show')}});
 $('#cr-int-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','create_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo guardar.');returnToDetail=false;$('#crInterventionModal').modal('hide');alertMsg(d.message,'success');this.reset();load()}catch(x){alertMsg(x.message,'danger')}});
 $(document).on('click','.cr-edit',function(){let id=Number($(this).data('id')),r=(cache?.interventions||[]).find(x=>Number(x.id)===id);if(!r)return;$('#cr-up-id').val(r.id);$('#cr-up-label').html('<strong>'+esc(r.student_name)+'</strong><br>'+esc(r.course_name||'Intervención general histórica')+' · '+esc(r.title));$('#cr-up-status').val(r.status);$('#cr-up-outcome').val(r.outcome||'');$('#cr-up-followup').val(r.followup_date||'');$('#cr-up-notes').val(r.notes||'');$('#crUpdateModal').modal('show')});
 $('#cr-up-form').on('submit',async function(e){e.preventDefault();let fd=new FormData(this);fd.set('action','update_intervention');fd.set('csrf_token',CSRF);try{let r=await fetch(API,{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'No se pudo actualizar.');$('#crUpdateModal').modal('hide');alertMsg(d.message,'success');load()}catch(x){alertMsg(x.message,'danger')}});
 $('#cr-prev-page').on('click',function(){if(studentPage>1){studentPage--;renderStudentPage(cache?.students||[])}});$('#cr-next-page').on('click',function(){let totalPages=Math.max(1,Math.ceil((cache?.students||[]).length/STUDENTS_PER_PAGE));if(studentPage<totalPages){studentPage++;renderStudentPage(cache?.students||[])}});$('#cr-level').on('change',syncGrades);$('#cr-grade').on('change',syncSections);$('#cr-apply,#cr-refresh').on('click',load);$('#cr-clear').on('click',function(){$('#cr-search,#cr-level,#cr-grade,#cr-section,#cr-course,#cr-risk,#cr-bim').val('');syncGrades();load()});$('#cr-search').on('keydown',e=>{if(e.key==='Enter'){e.preventDefault();load()}});load();
})(jQuery);
</script>
